"use client";

/**
 * Access grant: two rows of team member cards stream by under a call-to-action
 * button. A pointer walks in and clicks it, and the cards switch from pending
 * to granted one after another, each with a check.
 *
 * Written by Better Design. Painted from the theme prop; avatars are initials
 * on tints of the primary colour.
 */
import { loadFont } from "@remotion/google-fonts/Inter";
import { AbsoluteFill, interpolate, spring, useCurrentFrame, useVideoConfig } from "remotion";
import { easings, pickFont, progress, shiftHue, springs, type VideoTheme, useVideoTheme, withAlpha } from "@/lib/bd-video";

const { fontFamily: INTER } = loadFont("normal", { weights: ["500", "600", "700"], subsets: ["latin"] });

const STREAM_FRAMES = 112;
const TRAVEL = 720;
const CARD_W = 480;
const CARD_H = 124;
const PITCH = CARD_W + 28;
const PER_ROW = 7;
const ROW_TOPS = [500, 656];
const BUTTON_Y = 300;
const POINTER_IN = 26;
const CLICK_AT = 62;
/** Frames the grant wave takes to cross the frame, after the click. */
const WAVE = 38;

export interface AccessGrantProps {
  /** The button label the pointer clicks. */
  cta?: string;
  /** Member names, reused in order across both rows. */
  members?: string[];
  theme?: Partial<VideoTheme>;
  /** A CSS font family the project has loaded. Defaults to the theme's face, then Inter. */
  font?: string;
}

const initials = (name: string) =>
  name
    .split(/\s+/)
    .map((part) => part[0] ?? "")
    .join("")
    .slice(0, 2)
    .toUpperCase();

function Check({ color, size }: { color: string; size: number }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none">
      <path d="M5 12.5l4.5 4.5L19 7.5" stroke={color} strokeWidth={3} strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  );
}

function MemberCard({ theme, name, hue, granted }: { theme: VideoTheme; name: string; hue: number; granted: number }) {
  const tint = shiftHue(theme.primary, hue);
  return (
    <div
      style={{
        width: CARD_W,
        height: CARD_H,
        display: "flex",
        alignItems: "center",
        gap: 20,
        padding: "0 24px",
        borderRadius: theme.radius * 1.5,
        background: theme.card,
        border: `2px solid ${granted > 0.5 ? withAlpha(theme.primary, 0.5) : theme.border}`,
        boxShadow: `0 14px 36px oklch(0 0 0 / 0.07)`,
      }}
    >
      <div style={{ width: 64, height: 64, borderRadius: 32, flexShrink: 0, display: "flex", alignItems: "center", justifyContent: "center", background: withAlpha(tint, 0.18), color: tint, fontSize: 24, fontWeight: 700 }}>
        {initials(name)}
      </div>
      <div style={{ flex: 1, minWidth: 0, fontSize: 28, fontWeight: 600, color: theme.cardForeground, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{name}</div>
      <div style={{ position: "relative", width: 132, height: 44, flexShrink: 0 }}>
        <div style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center", borderRadius: 22, background: theme.muted, color: theme.mutedForeground, fontSize: 21, fontWeight: 600, opacity: 1 - Math.min(1, granted * 2) }}>
          Pending
        </div>
        <div
          style={{
            position: "absolute",
            inset: 0,
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            gap: 6,
            borderRadius: 22,
            background: theme.primary,
            color: theme.primaryForeground,
            fontSize: 21,
            fontWeight: 600,
            opacity: Math.min(1, granted * 2),
            transform: `scale(${interpolate(granted, [0, 1], [0.6, 1])})`,
          }}
        >
          <Check color={theme.primaryForeground} size={22} />
          Granted
        </div>
      </div>
    </div>
  );
}

/** Member cards stream under a button; a pointer clicks it and each card turns granted. */
export function AccessGrant({
  cta = "Grant access",
  members = ["Maya Lin", "Sam Ortiz", "Priya Shah", "Leo Grant", "Ana Costa", "Tom Becker", "Ines Ruiz", "Kofi Mensah"],
  theme: themeOverride,
  font,
}: AccessGrantProps) {
  const theme = useVideoTheme(themeOverride);
  const frame = useCurrentFrame();
  const { fps } = useVideoConfig();
  const family = pickFont(font, theme, INTER);
  const names = members.length > 0 ? members : ["Team member"];

  const stream = easings.out(progress(frame, 0, STREAM_FRAMES));
  const enter = easings.out(progress(frame, 0, 14));
  const spanWidth = PER_ROW * PITCH - 28;

  const walk = easings.inOut(progress(frame, POINTER_IN, CLICK_AT - POINTER_IN));
  const pointerX = interpolate(walk, [0, 1], [1640, 1040]);
  const pointerY = interpolate(easings.out(progress(frame, POINTER_IN, CLICK_AT - POINTER_IN)), [0, 1], [1120, BUTTON_Y + 22]);
  const press = progress(frame, CLICK_AT, 4) - progress(frame, CLICK_AT + 4, 8);
  const ripple = easings.out(progress(frame, CLICK_AT + 2, 26));
  const buttonIn = easings.out(progress(frame, 6, 18));

  return (
    <AbsoluteFill style={{ background: theme.background, fontFamily: family, overflow: "hidden" }}>
      <div
        style={{
          position: "absolute",
          inset: 0,
          opacity: enter,
          maskImage: "linear-gradient(90deg, transparent 0%, black 14%, black 86%, transparent 100%)",
        }}
      >
        {ROW_TOPS.map((top, row) => {
          const direction = row === 0 ? -1 : 1;
          const finalLeft = (1920 - spanWidth) / 2 + (row === 0 ? -PITCH / 4 : PITCH / 4);
          const left = finalLeft - direction * TRAVEL * (1 - stream);
          return Array.from({ length: PER_ROW }, (_, k) => {
            const index = (k + row * 3) % names.length;
            const finalX = finalLeft + k * PITCH;
            const across = (finalX + CARD_W / 2) / 1920;
            const grantAt = CLICK_AT + 8 + Math.max(0, Math.min(1, across)) * WAVE + row * 4;
            const granted = spring({ frame: frame - grantAt, fps, config: springs.snappy });
            return (
              <div key={`${row}-${k}`} style={{ position: "absolute", top, left: left + k * PITCH }}>
                <MemberCard theme={theme} name={names[index]} hue={index * 41} granted={granted} />
              </div>
            );
          });
        })}
      </div>
      <div style={{ position: "absolute", left: 0, right: 0, top: BUTTON_Y - 50, display: "flex", justifyContent: "center" }}>
        <div style={{ position: "relative", opacity: buttonIn, transform: `translateY(${(1 - buttonIn) * 20}px) scale(${1 - press * 0.05})` }}>
          <div
            style={{
              position: "absolute",
              inset: 0,
              borderRadius: 999,
              border: `3px solid ${theme.primary}`,
              opacity: (1 - ripple) * (frame >= CLICK_AT ? 0.7 : 0),
              transform: `scale(${1 + ripple * 0.35}, ${1 + ripple * 0.9})`,
            }}
          />
          <div
            style={{
              height: 100,
              padding: "0 56px",
              display: "flex",
              alignItems: "center",
              borderRadius: 999,
              background: theme.primary,
              color: theme.primaryForeground,
              fontSize: 40,
              fontWeight: 600,
              letterSpacing: "-0.01em",
              boxShadow: `0 20px 50px ${withAlpha(theme.primary, 0.32)}`,
            }}
          >
            {cta}
          </div>
        </div>
      </div>
      <svg
        width={44}
        height={60}
        viewBox="0 0 24 32"
        style={{ position: "absolute", left: pointerX, top: pointerY, opacity: progress(frame, POINTER_IN, 6), transform: `scale(${1 - press * 0.1})`, transformOrigin: "0 0", filter: `drop-shadow(0 6px 10px oklch(0 0 0 / 0.25))` }}
      >
        <path d="M2 2 L2 26 L8.5 20 L13 30 L17 28.2 L12.6 18.6 L21 18.6 Z" fill={theme.foreground} stroke={theme.background} strokeWidth={1.6} strokeLinejoin="round" />
      </svg>
    </AbsoluteFill>
  );
}
